    int count = 0;
    const int INF = 1000000000;
    const int NEG = -1000000000;

    for (int idx = N - 1; idx >= 0; --idx) {
        int u = order[idx];
        int du = 0;
        int cu = INF;

        for (int e = head[u]; e != -1; e = nxt[e]) {
