        to[edge] = b;
        nxt[edge] = head[a];
        head[a] = edge++;
        to[edge] = a;
        nxt[edge] = head[b];
        head[b] = edge++;
    }

    int *stack = (int *)malloc(N * sizeof(int));
    int top = 0;
    stack[top++] = 1;
    parent[1] = 0;
    int ord_idx = 0;

    while (top > 0) {
        int u = stack[--top];
        order[ord_idx++] = u;
        for (int e = head[u]; e != -1; e = nxt[e]) {
